public class AuthObserveAN01V38 {
 public static String observe(){
  Map<String,Object> payload=new Map<String,Object>();
  payload.put('isTest',Test.isRunningTest());
  try{payload.put('networkId',Network.getNetworkId());}catch(Exception e){payload.put('networkContextException',e.getTypeName()+'|'+e.getMessage());}
  try{payload.put('siteId',Site.getSiteId());}catch(Exception e){payload.put('siteContextException',e.getTypeName()+'|'+e.getMessage());}
  payload.put('stage','call');
  try{PageReference result=Network.forwardToAuthPage(null,null); page(payload,result);}catch(Exception e){payload.put('outcome','EXC');payload.put('exceptionType',e.getTypeName());payload.put('exceptionMessage',e.getMessage());}
  return JSON.serialize(payload);
 }
 private static void page(Map<String,Object> payload,PageReference result){
  payload.put('outcome',result==null?'NULL':'PAGE');
  if(result!=null){payload.put('url',result.getUrl());payload.put('redirect',result.getRedirect());}
 }
}

